package com.financialfraudassistant.controller;
import com.financialfraudassistant.dto.GoalRequest; import com.financialfraudassistant.model.*; import com.financialfraudassistant.repository.FinancialGoalRepository; import com.financialfraudassistant.service.CurrentUserService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api/goals") public class GoalController { private final FinancialGoalRepository repo; private final CurrentUserService users; public GoalController(FinancialGoalRepository r,CurrentUserService u){repo=r;users=u;} @GetMapping public List<FinancialGoal> list(Authentication a){return repo.findByUserIdOrderByCreatedAtDesc(users.requireUser(a).getId());} @PostMapping public FinancialGoal create(Authentication a,@Valid @RequestBody GoalRequest r){User u=users.requireUser(a);return repo.save(new FinancialGoal(u,r.name().trim(),r.targetAmount(),r.currentAmount()==null?BigDecimal.ZERO:r.currentAmount(),r.deadline(),r.monthlyContribution()==null?BigDecimal.ZERO:r.monthlyContribution()));} }
